package com.rtsbuilding.rtsbuilding.server.service.page;
import com.rtsbuilding.rtsbuilding.network.storage.S2CRtsStoragePagePayload; import com.rtsbuilding.rtsbuilding.server.RtsStorageUiPayloads; import com.rtsbuilding.rtsbuilding.server.storage.RtsStorageBindings; import com.rtsbuilding.rtsbuilding.server.storage.model.LinkedStorageRef; import com.rtsbuilding.rtsbuilding.server.storage.resolver.RtsLinkedStorageResolver; import com.rtsbuilding.rtsbuilding.server.storage.session.RtsStorageSession;
import net.minecraft.entity.player.EntityPlayerMP; import net.minecraft.item.Item; import net.minecraft.item.ItemStack; import net.minecraft.util.ResourceLocation; import net.minecraft.util.math.BlockPos; import net.minecraft.world.WorldServer; import net.minecraftforge.fml.common.registry.ForgeRegistries;
import java.util.*;
public final class RtsPagePayloadFactory {
 private RtsPagePayloadFactory(){}
 public static S2CRtsStoragePagePayload buildEmpty(EntityPlayerMP player,RtsStorageSession session){LinkedRefPayload refs=buildLinkedRefPayload(player,session);int q=RtsStorageBindings.QUICK_SLOT_COUNT,g=RtsStorageBindings.GUI_BINDING_SLOT_COUNT;return new S2CRtsStoragePagePayload(RtsLinkedStorageResolver.hasAnyStorage(player,session),RtsLinkedStorageResolver.buildAnyStorageSummary(player,session),refs.positions(),refs.names(),refs.modes(),refs.priorities(),refs.iconItemIds(),refs.worldAvailable(),0,1,0,true,session.browser.search,session.browser.category,(byte)session.browser.sort.ordinal(),session.browser.ascending,session.sessionFlags.autoStoreMinedDrops,session.sessionFlags.useBdNetwork,Collections.singletonList(RtsPageSharedHelpers.CATEGORY_ALL),Collections.<ItemStack>emptyList(),Collections.<Long>emptyList(),Collections.<String>emptyList(),Collections.<Long>emptyList(),Collections.<String>emptyList(),Collections.<Long>emptyList(),Collections.<Long>emptyList(),Collections.<String>emptyList(),Collections.<Long>emptyList(),Collections.<Long>emptyList(),Collections.<Byte>emptyList(),RtsStorageUiPayloads.buildQuickSlotPayload(session,q),RtsStorageUiPayloads.buildQuickSlotPreviewPayload(session,q),RtsStorageUiPayloads.buildGuiBindingLabelPayload(session,g),RtsStorageUiPayloads.buildGuiBindingItemIdPayload(session,g),session.funnel.funnelEnabled,Collections.<String>emptyList(),Collections.<Long>emptyList());}
 public static LinkedRefPayload buildLinkedRefPayload(EntityPlayerMP player,RtsStorageSession session){if(player==null||session==null||session.linkedStorageInfo.isEmpty())return emptyRefs();WorldServer world=player.getServerWorld();List<Long>pos=new ArrayList<Long>();List<String>names=new ArrayList<String>(),icons=new ArrayList<String>();List<Byte>modes=new ArrayList<Byte>();List<Integer>priorities=new ArrayList<Integer>();List<Boolean>visibleList=new ArrayList<Boolean>();for(LinkedStorageRef ref:session.linkedStorageInfo.getAll()){boolean backpack=ref!=null&&session.linkedStorageInfo.hasBackpackUuid(ref);if(ref==null||ref.pos()==null||(!backpack&&ref.dimension()!=player.dimension))continue;boolean visible=RtsLinkedStorageResolver.isLinkedRefWorldVisible(player,session,ref);pos.add(ref.pos().toLong());names.add(resolveName(world,session,ref,visible));modes.add(session.linkedStorageInfo.getMode(ref));priorities.add(RtsLinkedStorageResolver.sanitizeLinkedStoragePriority(session.linkedStorageInfo.getPriority(ref)));icons.add(resolveIcon(world,session,ref,visible));visibleList.add(visible);}return new LinkedRefPayload(pos,names,modes,priorities,icons,visibleList);}
 private static LinkedRefPayload emptyRefs(){return new LinkedRefPayload(Collections.<Long>emptyList(),Collections.<String>emptyList(),Collections.<Byte>emptyList(),Collections.<Integer>emptyList(),Collections.<String>emptyList(),Collections.<Boolean>emptyList());}
 private static String resolveName(WorldServer world,RtsStorageSession session,LinkedStorageRef ref,boolean visible){if(visible&&world!=null&&world.isBlockLoaded(ref.pos()))return RtsLinkedStorageResolver.resolveDisplayName(world,ref.pos());String cached=session.linkedStorageInfo.getName(ref);return cached==null||cached.trim().isEmpty()?"Linked Storage":cached;}
 private static String resolveIcon(WorldServer world,RtsStorageSession session,LinkedStorageRef ref,boolean visible){if(!visible){String id=session.linkedStorageInfo.getBackpackItemId(ref);return id==null?"":id;}Item item=Item.getItemFromBlock(world.getBlockState(ref.pos()).getBlock());ResourceLocation id=ForgeRegistries.ITEMS.getKey(item);return id==null?"":id.toString();}
 /** 仅供旧 payload 显示汇总；真实 funnel 栈仍保留在 session 中，不在这里发生合并或变异。 */
 public static Map<String,Long> summarizeFunnelBuffer(RtsStorageSession session){Map<String,Long>counts=new TreeMap<String,Long>();if(session==null)return new LinkedHashMap<String,Long>();for(ItemStack stack:session.funnel.funnelBuffer){if(stack==null||stack.isEmpty())continue;ResourceLocation id=ForgeRegistries.ITEMS.getKey(stack.getItem());if(id==null)continue;Long old=counts.get(id.toString());counts.put(id.toString(),RtsPageCore.saturatedAdd(old==null?0:old.longValue(),stack.getCount()));}return new LinkedHashMap<String,Long>(counts);}
}
